'use strict';

// MODULES //

var resolve = require( 'path' ).resolve;
var findPkgs = require( '@stdlib/_tools/pkgs/find' ).sync;
var rootDir = require( '@stdlib/_tools/utils/root-dir' );
var readJSON = require( '@stdlib/fs/read-json' ).sync;


// VARIABLES //

var ROOT_DIR = rootDir();
var jsonOpts = {
	'encoding': 'utf8'
};


// FUNCTIONS //

/**
* Returns the input and output dtypes for a given package by reading scaffold metadata.
*
* @private
* @param {string} pkgPath - package path
* @returns {Array} input and output dtypes
*
* @example
* var dtypes = getDtypes( '@stdlib/math/base/special/sqrt' );
* // returns [ 'float64', 'float64' ]
*
* @example
* var dtypes = getDtypes( '@stdlib/math/base/special/sqrtf' );
* // returns [ 'float32', 'float32' ]
*/
function getDtypes( pkgPath ) {
	var outputDtype;
	var inputDtype;
	var aliasName;
	var path;
	var json;
	var pkg;
	var out;
	var o;

	// Extract alias name from package path:
	aliasName = pkgPath.split( '/' ).pop();

	// Find the package:
	pkg = findPkgs({
		'dir': ROOT_DIR,
		'pattern': '**/math/base/special/' + aliasName + '/package.json' // Currently we are looking only in `math/base/special/`
	});

	if ( pkg.length === 0 ) {
		return [];
	}

	// Get the metadata:
	path = resolve( ROOT_DIR, pkg[ 0 ] );
	json = readJSON( resolve( path, 'package.json' ), jsonOpts );
	o = json.__stdlib__; // eslint-disable-line no-underscore-dangle
	if ( o && o.scaffold && o.scaffold.parameters.length >= 1 ) {
		out = o.scaffold;
	}

	// Extract input and output dtypes:
	inputDtype = out.parameters[ 0 ].type.dtype;
	outputDtype = out.returns.type.dtype;

	return [ inputDtype, outputDtype ];
}


// EXPORTS //

module.exports = getDtypes;
